import AppKit
import Foundation
import Metal
import RealityKit

/// Keeps the authored paper material and Blender display response together.
/// The lookup is generated by Blender's actual AgX processor, not a palette edit.
@MainActor
enum PsiloRenderStyle {
    private static var pipelines: [String: PsiloColorPipeline] = [:]

    @discardableResult
    static func installColorTransform(on view: ARView, lookupURL: URL?, debugLogging: Bool) -> PsiloDisplaySession? {
        guard let lookupURL, let device = MTLCreateSystemDefaultDevice() else {
            NSLog("NeaTree: Psilo display transform could not be prepared; using native rendering.")
            return nil
        }
        let key = "\(device.registryID):\(lookupURL.standardizedFileURL.path)"
        let pipeline: PsiloColorPipeline
        if let cached = pipelines[key] {
            pipeline = cached
        } else {
            guard let data = try? Data(contentsOf: lookupURL), data.count == 33 * 33 * 33 * 8,
                  let prepared = try? PsiloColorPipeline(device: device, data: data) else {
                NSLog("NeaTree: Psilo display transform could not be prepared; using native rendering.")
                return nil
            }
            pipeline = prepared
            pipelines[key] = prepared
        }
        // Register the complete callbacks before the view starts rendering.
        // Changing them after its first frame is unsupported on the current SDK.
        var callbacks = ARView.RenderCallbacks()
        let session = PsiloDisplaySession(pipeline: pipeline, debugLogging: debugLogging)
        callbacks.prepareWithDevice = { _ in }
        callbacks.postProcess = session.callback()
        view.renderCallbacks = callbacks
        if debugLogging { NSLog("Psilo display: AgX lookup, one GPU pass, 33³ half-float samples") }
        return session
    }

    static func restoreAuthoredMaterials(in root: Entity) {
        if var model = root.components[ModelComponent.self] {
            model.materials = model.materials.map { material in
                guard var paper = material as? PhysicallyBasedMaterial else { return material }
                // UsdPreviewSurface's authored specular values import as 0.5 in
                // RealityKit. This asset has a textured paper atlas and plain Ink.
                // Restore the exact 0.12/0.22 values from the v7 USD contract.
                paper.specular = .init(scale: paper.baseColor.texture == nil ? 0.22 : 0.12)
                return paper
            }
            root.components.set(model)
        }
        for child in root.children { restoreAuthoredMaterials(in: child) }
    }

    static func makeLight() -> DirectionalLight {
        let light = DirectionalLight()
        light.light.intensity = 1_100
        light.light.color = NSColor(srgbRed: 1, green: 0.98, blue: 0.95, alpha: 1)
        light.shadow = nil
        light.look(at: .zero, from: [-0.4, 0.7, 0.6], relativeTo: nil)
        return light
    }
}

/// The renderer's output profile is not necessarily NSWindow.colorSpace. Probe
/// its own image once after creation and again after a display/backing change.
/// No snapshots, image conversions, or file reads occur in the frame callback.
@MainActor
final class PsiloDisplaySession {
    private let state: PsiloDisplayState
    private let debugLogging: Bool
    private var probeTask: Task<Void, Never>?
    private var generation = UUID()

    fileprivate init(pipeline: PsiloColorPipeline, debugLogging: Bool) {
        state = PsiloDisplayState(pipeline: pipeline, debugLogging: debugLogging)
        self.debugLogging = debugLogging
    }

    func callback() -> (ARView.PostProcessContext) -> Void { state.callback() }

    func refreshProfile(of view: ARView) {
        cancel()
        state.setGamut(0)
        let expected = generation
        probeTask = Task { [weak self, weak view] in
            do { try await Task.sleep(for: .milliseconds(150)) } catch { return }
            guard let self, let view, !Task.isCancelled else { return }
            view.snapshot(saveToHDR: false) { [weak self] image in
                let profile = image?.cgImage(forProposedRect: nil, context: nil, hints: nil)?.colorSpace
                Task { @MainActor [weak self] in
                    guard let self, self.generation == expected else { return }
                    let gamut = Self.gamut(for: profile)
                    self.state.setGamut(gamut)
                    if self.debugLogging {
                        NSLog("Psilo output profile: %@ (transform=%u)", profile?.name as String? ?? "unknown", gamut)
                    }
                }
            }
        }
    }

    func cancel() {
        generation = UUID()
        probeTask?.cancel()
        probeTask = nil
    }

    private static func gamut(for profile: CGColorSpace?) -> UInt32 {
        guard let profile else { return 0 }
        if profile == CGColorSpace(name: CGColorSpace.displayP3) { return 2 }
        if profile == CGColorSpace(name: CGColorSpace.sRGB) { return 1 }
        // Unknown ICC profiles use RealityKit's unchanged output, rather than
        // assuming every monitor uses P3 or applying a guessed color matrix.
        return 0
    }
}

private final class PsiloDisplayState: @unchecked Sendable {
    private let pipeline: PsiloColorPipeline
    private let lock = NSLock()
    private var gamut: UInt32 = 0
    private let debugLogging: Bool
    private var lastReportedGamut: UInt32 = .max
    init(pipeline: PsiloColorPipeline, debugLogging: Bool) {
        self.pipeline = pipeline
        self.debugLogging = debugLogging
    }
    func setGamut(_ value: UInt32) { lock.lock(); gamut = value; lock.unlock() }
    func callback() -> (ARView.PostProcessContext) -> Void {
        { [self] context in
            lock.lock()
            let value = gamut
            let shouldReport = debugLogging && lastReportedGamut != value
            lastReportedGamut = value
            lock.unlock()
            if shouldReport {
                NSLog("Psilo render buffers: source=%lu, target=%lu, gamut=%u, device=%llu/%llu",
                      context.sourceColorTexture.pixelFormat.rawValue,
                      context.targetColorTexture.pixelFormat.rawValue, value,
                      context.device.registryID, pipeline.deviceIdentifier)
            }
            pipeline.process(context, gamut: value)
        }
    }
}

/// Immutable after creation. Metal invokes this callback on its render thread;
/// the only CPU work per frame is encoding a single small compute dispatch.
fileprivate final class PsiloColorPipeline: @unchecked Sendable {
    private let pipeline: any MTLComputePipelineState
    private let lookup: any MTLTexture
    var deviceIdentifier: UInt64 { pipeline.device.registryID }

    init(device: any MTLDevice, data: Data) throws {
        let library = try device.makeLibrary(source: Self.shader, options: nil)
        guard let function = library.makeFunction(name: "psiloDisplayTransform") else { throw PipelineError.unavailable }
        pipeline = try device.makeComputePipelineState(function: function)
        let descriptor = MTLTextureDescriptor()
        descriptor.textureType = .type3D
        descriptor.pixelFormat = .rgba16Float
        descriptor.width = 33
        descriptor.height = 33
        descriptor.depth = 33
        descriptor.usage = .shaderRead
        guard let texture = device.makeTexture(descriptor: descriptor) else { throw PipelineError.unavailable }
        lookup = texture
        data.withUnsafeBytes { bytes in
            texture.replace(region: MTLRegionMake3D(0, 0, 0, 33, 33, 33), mipmapLevel: 0, slice: 0,
                            withBytes: bytes.baseAddress!, bytesPerRow: 33 * 8, bytesPerImage: 33 * 33 * 8)
        }
    }

    func process(_ context: ARView.PostProcessContext, gamut: UInt32) {
        guard context.device.registryID == pipeline.device.registryID,
              let encoder = context.commandBuffer.makeComputeCommandEncoder() else {
            if context.sourceColorTexture.pixelFormat == context.targetColorTexture.pixelFormat,
               let copy = context.commandBuffer.makeBlitCommandEncoder() {
                copy.copy(from: context.sourceColorTexture, to: context.targetColorTexture)
                copy.endEncoding()
            }
            return
        }
        encoder.setComputePipelineState(pipeline)
        encoder.setTexture(context.sourceColorTexture, index: 0)
        encoder.setTexture(context.targetColorTexture, index: 1)
        encoder.setTexture(lookup, index: 2)
        // Screen frames use sRGB buffers. ARView's non-HDR snapshot uses linear
        // rgba16Float buffers; the constant-color source/target probes verify
        // both contracts. Unknown formats (including plain UNORM) pass through.
        let sourceFormat = context.sourceColorTexture.pixelFormat
        let targetFormat = context.targetColorTexture.pixelFormat
        let supportsLinearTransfer = Self.usesVerifiedLinearTransfer(sourceFormat)
            && Self.usesVerifiedLinearTransfer(targetFormat)
        var outputGamut: UInt32 = supportsLinearTransfer ? gamut : 0
        encoder.setBytes(&outputGamut, length: MemoryLayout<UInt32>.size, index: 0)
        encoder.dispatchThreads(MTLSize(width: context.targetColorTexture.width,
                                       height: context.targetColorTexture.height, depth: 1),
                                threadsPerThreadgroup: MTLSize(width: 8, height: 8, depth: 1))
        encoder.endEncoding()
    }

    private static func usesVerifiedLinearTransfer(_ format: MTLPixelFormat) -> Bool {
        format == .bgra8Unorm_srgb || format == .rgba8Unorm_srgb || format == .rgba16Float
    }

    private enum PipelineError: Error { case unavailable }

    private static let shader = """
    #include <metal_stdlib>
    using namespace metal;
    kernel void psiloDisplayTransform(texture2d<float, access::read> source [[texture(0)]],
                                     texture2d<float, access::write> target [[texture(1)]],
                                     texture3d<float, access::sample> lookup [[texture(2)]],
                                     constant uint & gamut [[buffer(0)]],
                                     uint2 pixel [[thread_position_in_grid]]) {
        if (pixel.x >= target.get_width() || pixel.y >= target.get_height()) return;
        float4 color = source.read(pixel);
        if (gamut == 0) { target.write(color, pixel); return; }
        if (color.a <= 0.00001) { target.write(float4(0), pixel); return; }
        // Native sRGB texture reads decode to linear. The +1.2 EV lighting
        // calibration is separate from the source look's baked +0.4 EV.
        float3 linear = color.rgb / color.a;
        if (gamut == 2) {
            // Display P3 D65 linear primaries -> Rec.709 D65 linear primaries.
            linear = float3(dot(linear, float3(1.224745, -0.224904, 0.0)),
                            dot(linear, float3(-0.042058, 1.042081, 0.0)),
                            dot(linear, float3(-0.019642, -0.078655, 1.098537)));
        }
        linear *= 2.29739671;
        float3 logInput = clamp((log2(max(linear, float3(0.000244140625))) + 12.0) / 16.0, 0.0, 1.0);
        float3 coordinate = logInput * (32.0 / 33.0) + (0.5 / 33.0);
        constexpr sampler sampleLookup(coord::normalized, address::clamp_to_edge, filter::linear);
        float3 display = lookup.sample(sampleLookup, coordinate).rgb;
        // The generated LUT contains display-sRGB values. Decode before the
        // destination sRGB texture encodes them, and preserve premultiplied alpha.
        float3 result = select(display / 12.92, pow((display + 0.055) / 1.055, float3(2.4)), display > 0.04045);
        if (gamut == 2) {
            result = float3(dot(result, float3(0.822593, 0.177534, 0.0)),
                            dot(result, float3(0.033200, 0.966784, 0.0)),
                            dot(result, float3(0.017085, 0.072396, 0.910301)));
        }
        target.write(float4(result * color.a, color.a), pixel);
    }
    """
}
